-- The makers' own tasting notes from the pages the importers cached (scripts/bourbon_notes.py), 2026-10-13: one product_reviews row per product and page,
-- source = the maker's domain, reviewer = the maker. They give `pnpm seed:enrich --type bourbon` text to build a baseline taste wheel from.
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "0ab010a6-074d-43b6-8f64-224d2eda413f", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/cask-strength/", "reviewer": "A. Smith Bowman", "text": "LIMITED EDITION CASK STRENGTH| Our Limited Edition Cask Strength Virginia Straight Bourbon Whiskey was aged for 10 years, and features delightful aromas of vanilla, apple, and dried cherries. Taste the flavors of wonderful toasted pecan and candied nuts which give way to brown sugar, brown spice, and toasted coconut. This bourbon is bottled uncut and non-chill-filtered, with an oily and viscous aftertaste that keeps going long after the final sip.| VISIT US|"}, {"product_id": "3b5424da-a347-48ba-9a4b-062eda8df579", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/rye-whiskey/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 1 | Rye Whiskey| Our Rye Whiskey was the first release in the Abraham Bourbon line, | spanning | back to | 2001| . It features rye grain, peppery spices, and a slight hint of toffee followed by mint and eucalyptus notes. It embodies a gently long finish that makes it the perfect rye to sip neat.| VISIT US| *Sold Out|"}, {"product_id": "b5f93c03-08ad-43e1-8fc2-9ec24c082061", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/bourbon-whiskey-2011/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 2 | Bourbon Whiskey| At 18 years of age, our 2011 Bourbon Whiskey is presented at cask strength. Big on flavor, with surprisingly minimal heat, it features a tasteful blend of dark fruit, sweet plum, and caramel.| VISIT US| *Sold Out|"}, {"product_id": "8f80fd88-8262-4dc6-bcb7-ea543ca64aa3", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/port-finished-bourbon-2012/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 4 | Port Finished Bourbon| Our 2012 Port Finished Bourbon is full of rich flavors including chocolate and vanilla with a touch of plum and distinct wood notes. The barrels aged for four years at our distillery then were shipped to Potomac Point Winery in Stafford, Virginia and filled with port. This bourbon has the taste of candied apples, dark fruits, and figs.| VISIT US| *Sold Out|"}, {"product_id": "10bc8745-e68f-4ddd-8958-31cb6dd1aa16", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/last-millennium-bourbon-whiskey/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 5 | Last Millennium Bourbon Whiskey| Our Last Millennium Bourbon Whiskey was released in 2013 and embodies a sweet and inviting taste of caramel, honey, and maple syrup. | It is | composed of a 16-year-old bourbon distilled in 1997 and 14-year-old bourbon distilled in 1999 — | hence the name Last Millennium!| VISIT US| *Sold Out|"}, {"product_id": "1ac75fc0-3c7f-4121-8f4b-d4c300d781ba", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/gingerbread-beer-finished-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 6 | Gingerbread Beer Finished Bourbon| Our Gingerbread Beer Finished Bourbon was released in 2013 | with tasting notes of gingerbread spice, toasted nuts, and cinnamon.| The barrels used for this bourbon had quite a journey, originally aging Bowman Brothers Bourbon from 2004 to 2012.| In 2012, the barrels were given to Hardywood Brewery in Richmond, Virginia where they aged their award-winning Gingerbread Stout inside for 12 weeks before being returned to us.| VISIT US| *Sold Out|"}, {"product_id": "a847fbf9-e24e-42f9-abbd-8c7de6599928", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/double-barrel-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 8 | Double Barrel Bourbon| Our Double Barrel Bourbon was released in 2014 and features aromas of cinnamon and caramel. The non-chill filtered spirit is smooth and sweet in the mouth, with a pleasant marriage of spice, vanilla, and toasty oak flavors. This is a bourbon lover's bourbon that lingers delicately on the palate.| VISIT US| *Sold Out|"}, {"product_id": "7a7b2238-05a6-47f9-b329-b850b9606b6f", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/cider-finished-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 9 | Cider Finished Bourbon| Our Cider Finished Bourbon release in 2014 was aged for six months| in apple cider barrels from Distillery Lane Cider Works. Those same barrels were used to age Mt. Vernon Heritage Cider — a blend of | Hews, Crabapple, Newtown Pippen, and Roxbury Russet apples. | This complex, yet sweet bourbon | has | deep toasted oak notes highlighted with dried fruit, honey, and brown sugar.| VISIT US| *Sold Out|"}, {"product_id": "341b6361-9c89-4715-b0fc-c5adc5a82d7d", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/vanilla-bean-infused/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 10 | Vanilla Bean Infused 24 Months| Our Vanilla Bean Infused Bourbon was infused for 24 months and resulted in a creamy mix of cinnamon, oak, and marzipan. | After aging for a total of seven years and six months in the barrel, the bourbon was infused with chopped Madagascar vanilla beans before marrying the barrels together in 2014, creating a sweet oak, vanilla, and dark spice flavor.| VISIT US| *Sold Out|"}, {"product_id": "11676a94-b29b-443c-aca0-75fb9c4c8fb4", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/wheat-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 14 | Wheat Bourbon| Our 2016 Wheat Bourbon release | is | creamy with caramels chews, vanilla, and cinnamon. The combination of toasted oak and freshly-baked wheat bread create a slightly spicy, yet delightful finish.| VISIT US| *Sold Out|"}, {"product_id": "db9caaa8-d0d8-4a4f-916f-8302b98891e0", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/gingerbread-cocoa-finished-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 15 | Gingerbread Cocoa Finished Bourbon| Our | Gingerbread Cocoa Finished Bourbon| was released in 2016 and | has| a flavorful nose of chocolate dipped gingerbread cookies, toasted | nuts| , and vanilla. We worked with our good friends at Hardywood Park Craft Brewery in Richmond, Virginia to create this smoothly rich spirit.| VISIT US| *Sold Out|"}, {"product_id": "2b89d451-3ff7-488e-9f01-8c7d7a9e902d", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/sequential-2nd-use-barrels/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 16 | Sequential Series | 2nd Use Barrels| The Sequential Series is comprised of two expressions resulting from an experiment in barrel use and entry proof. For our 2nd Use Barrels release, we transferred nine-year-old bourbon from its new charred white oak barrels into barrels that had previously held bourbon for nine years. Half the barrels entered at 125 proof while the other half entered at 115 proof. The final marriage features notes of baked apples, vanilla and sweet caramel – worthy of sipping slowly.| Both 2nd & 4th Use Barrels were released in 2017.| VISIT"}, {"product_id": "39b5fca3-716a-45a3-a495-bd5a39326db0", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/bourbon-whiskey-2019/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 18 | Bourbon Whiskey| This extremely limited 2019 release resulted thanks to a failed experiment, which ultimately led to a pleasant surprise. It offers sweet vanilla and toasted oak on the nose, with cherry, baked apple and rye spice in the background. Having a nice sweet flavor and slight nuttiness, this bourbon is soft and well-mannered despite the high proof.| VISIT US| *Sold Out|"}, {"product_id": "5faae3cf-49f9-4091-bfa8-6c8e42f441ac", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/twice-finished-whiskey-2019/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 19 | Twice Finished Whiskey| This limited release began in December 2006 when seven charred oak barrels were filled and laid to age peacefully for eight years and three months. From there, these barrels were consolidated into two-and-a-half barrels to be finished. First the whiskey was finished in Potomac Point Winery port barrels for four years and seven months. Then it was transferred into sauterne barrels for two months before being bottled, bringing the total age of this whiskey to 13 years.| Tasting notes describe “upfront notes of sweet honey, and caramel wit"}, {"product_id": "c7bd9aba-0ed7-4930-8f84-a2ce00f8af41", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/gingerbread-2/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 20 | Gingerbread #2| Our 110 proof Gingerbread #2 was aged for 10 years and features delightful aromas of ginger and brown spice galore, with strong notes of vanilla and hints of nutmeg. Taste the flavors of wonderful toasted oak with caramel pralines moving almost to a hint of graham cracker and fig. This bourbon has a medium mouthfeel with a huge impact of flavor; sweet confectionary notes that warm the palate and finishes with a flavor that lingers pleasantly without overstaying its welcome.| VISIT US|"}, {"product_id": "79f18c79-665b-42a1-8398-a91786fc9217", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/rum-finished-bourbon/", "reviewer": "A. Smith Bowman", "text": "ABRAHAM BOWMAN| Release No. 21 | Rum Finished Bourbon| This | limited edition release| began in 2006 when two barrels of American Oak were aged gracefully for nine years. Afterward, the contents of the barrels were transferred to Caribbean rum casks for another six years, bringing the total age of this bourbon to 15 years. Extremely rare, this release may just be the oldest rum cask finished bourbon ever produced. | Tasting notes describe the aroma of vanilla, caramel, and candied nuts that give way to leather and coconut. Finally fading to the notes brought in from the long rum finish, aroma"}, {"product_id": "7d0e8a4c-1f2e-48b7-bdd4-df5da81affc6", "source": "bluegrassdistillers.com", "source_url": "https://bluegrassdistillers.com/products/100-proof-mash-bill-1-bourbon/", "reviewer": "Bluegrass", "text": "Our Mash Bill #1 Bourbon is our first mash bill of 75% corn, 21% rye , and 4% malted barley. This product is light and buttery on the palate with notes of nutmeg, cinnamon, spice herbal tea, caramel, black pepper, and anise. It finishes with lingering notes of cinnamon, nutmeg, leather, herbal mint and black pepper. Find a Store Near You"}, {"product_id": "32dc7b47-d1e9-4db3-afe6-7118c65e43c1", "source": "bluegrassdistillers.com", "source_url": "https://bluegrassdistillers.com/products/mash-bill-1-bottled-in-bond-bourbon/", "reviewer": "Bluegrass", "text": "Our Mash Bill #1 Bourbon is our first mash bill of 75% corn, 21% rye , and 4% malted barley. This product is light and buttery on the palate with notes of nutmeg, cinnamon, spice herbal tea, caramel, black pepper, and anise. It finishes with lingering notes of cinnamon, nutmeg, leather, herbal mint and black pepper. Find a Store Near You"}, {"product_id": "13b27005-8ef8-44e9-b9b2-409ce9a71184", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/caskfinished-amburana-cask-finished/", "reviewer": "Boone County", "text": "AMBURANA CASK FINISHED We finished our Founder's Reserve Bourbon in Amburana Brazilian Oak casks creating a distinctive new taste with delightful finishing notes of vanilla, clove, cinnamon and sweet ginger. Cheers! In the spirit of those who came before us… “Made By Ghosts”"}, {"product_id": "0e1e5c45-7f9f-437c-a910-b231b57f0868", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-dark-arts-whiskey-distilled-from-malt-mash/", "reviewer": "Breckenridge", "text": "Breckenridge Dark Arts: Whiskey Distilled from Malt Mash 46% ALC/VOL 92 PROOF A pioneering American Single Malt Whiskey, utilizing dark specialty malts and introducing them into standard malt mash. At the sacrifice of high yields, intentionally overpowering flavors such as over-ripe green apple, cacao, and chocolate dazzle the palate. We pushed the malt to the boundaries, purposefully off-balancing the undertones of bitter orange peel, angular oak, caramel, and green coffee cherries. Delightfully finishing with subtle essences of seaweed and sea salt. Up to ten years in a combination of new Am"}, {"product_id": "87d5d547-8601-4bf6-a6ab-9cc8c5ce2061", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-distillers-high-proof/", "reviewer": "Breckenridge", "text": "Breckenridge Distillers High Proof $59.99 52.5% ALC/VOL 105 PROOF Our Blended Bourbon Whiskey, but with a twist, bottled at a gripping 105 proof. Get a chance to experience what our distillers taste as they blend: a wild ride through rich, dark caramel and toasted almonds, burnt Baker's chocolate and dried orange peel, with a lingering finish of vanilla and spice. A masterful combination of mouthful flavors, furnish our Bourbon Whiskey to a deep, burnt orange hue. Try slowly adding water to enhance your experience."}, {"product_id": "89add309-72d6-43a3-8377-3e497bea71d9", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-double-barrel/", "reviewer": "Breckenridge", "text": "Breckenridge Double Barrel 46%% ALC/VOL 92 PROOF Breckenridge Double Barrel opens with an inviting aroma of finished leather and cherry‑laced tobacco, layered with rich caramel and seasoned oak. On the palate, robust notes of chocolate and caramel lead the way, balanced by a steady build of black pepper spice. The finish leans into deeply matured oak, lingering with warming spice and subtle hints of dark chocolate for a bold, well‑rounded sip."}, {"product_id": "d953c7d2-69c5-4175-b279-d8bdc310f07c", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-rum-cask-finish/", "reviewer": "Breckenridge", "text": "Breckenridge Rum Cask Finish $59.99 45% ALC/VOL 90 PROOF Our award-winning Breckenridge Bourbon soaks up the charm of our own aged Colorado Rum casks, creating an unstoppable wave of flavor. Candied apple and cinnamon enfold, as dark chocolate and cacao follow. Lingering allspice captivates the senses, gratifying in just one sip, but mysterious enough to leave you wanting another."}, {"product_id": "ba962682-a525-4366-a6cf-6b79e145c67d", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-rye-whiskey/", "reviewer": "Breckenridge", "text": "Breckenridge Rye Whiskey 50%% ALC/VOL 100 PROOF A complex nose unfolds with soft chocolate and fleeting hints of cherry that appear and fade with each pass, while subtle honeyed notes weave through alongside delicate hay and a gentle rye spice that adds an earthy, rustic lift. On the palate, light chocolate opens the experience, quickly building into richer caramel before easing back into cocoa tones, with hints of light stone fruit emerging mid‑palate and giving way to a bold, lingering rye spice that carries through a warm, enduring finish."}, {"product_id": "301f802a-724c-44a4-a44a-3c5c78c651ca", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-sexy-motor-oil/", "reviewer": "Breckenridge", "text": "Breckenridge Sexy Motor Oil 52.7% ALC/VOL 105.4 PROOF AROMA Cherry and roasted malt with light oak and brown sugar. PALATE Cherry and roasted bakers chocolate lingering through the finish. Learn more about Sexy Motor Oil: SERIES 5 * Available Exclusively at Breckenridge Distillery"}, {"product_id": "1b005c12-2654-4b05-83dd-5268c18155f5", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-whiskey-jamaican-rum-cask/", "reviewer": "Breckenridge", "text": "Breckenridge Whiskey Jamaican Rum Cask 45% ALC/VOL 90 PROOF Tropical fruit dominates the nose with mango, sweet plantains, and subtle pineapple. Over-ripe banana and sweet brown sugar lead to a brown sugar syrup and allspice finish."}, {"product_id": "73dc3f2c-fa22-4479-bc15-db8d68685d2b", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-whiskey-port-cask-finish/", "reviewer": "Breckenridge", "text": "Breckenridge Whiskey Port Cask Finish $59.99 45% ALC/VOL 90 PROOF Our award-winning Bourbon Whiskey gets some final grooming in 59 gallon Tawny Port casks, adding aroma and flavor of sultana raisin and maple syrup, which round out and soften the naturally spicy finish. Thanks to the superior Tawny Port casks, each batch flaunts a unique expression."}, {"product_id": "f1d0b81f-dc68-4bad-8024-8bc3d2c22fd0", "source": "breckenridgedistillery.com", "source_url": "https://breckenridgedistillery.com/spirits/breckenridge-whiskey-powder-hound/", "reviewer": "Breckenridge", "text": "Breckenridge Whiskey Powder Hound 45% ALC/VOL 90 PROOF Released in batches, Powder Hound Whiskey is a blend of bourbons from some of the oldest and best barrels in our library. Defined by a deep love for both powder days and our canine companions, every batch brings a very special Distiller's Blend inspired by our Head Distiller Hans Stafsholt. $5 from every bottle sale benefits a log canine-related charity. Batch 19: Powder Hound Whiskey opens with a bold aroma of rye spice, layered with subtle notes of fresh apple and seasoned oak. On the palate, rich caramel and well‑matured oak take the le"}, {"product_id": "ec5b6710-2c8a-4bdd-91b1-07fc3ae0091e", "source": "jackdaniels.com", "source_url": "https://www.jackdaniels.com/whiskey/distillery-series-14e19-twin-blend", "reviewer": "Brown-Forman", "text": "Twins might have completely different tastes, but because they share a birthday and family, their character complements one another. This is the secret behind Jack Daniel's 107 proof \"Twin\" Blend. We hand-selected 50 barrels of our Tennessee Whiskey and Tennessee Rye, all with a barrel entry date of May 19, 2014. Blended together and bottled at a flavorful 107 proof, \"Twin\" Blend complements Rye's spice with Tennessee Whiskey's sweet, floral accents for a doubly complex spirit. Selected by Master Taster Jessica Hartline. Available only in Tennessee."}, {"product_id": "f8c972a5-386e-4e91-865f-5f8ea8f73d12", "source": "jackdaniels.com", "source_url": "https://www.jackdaniels.com/whiskey/distillery-series-barrel-reunion-1", "reviewer": "Brown-Forman", "text": "A Reunion Worth Celebrating. As a whiskey maker and a barrel maker, we see the barrel not simply as a container but as an ingredient. This unique whiskey began with a hand-crafted barrel that matured Jack Daniel's. Once emptied, it aged fine Tennessee red wine. Then, finally it returned home to finish a small batch of our Tennessee Whiskey and delivers a 90-proof whiskey. What emerges from this second barreling are notes of caramel and oak with whispers of cherry and blackberry. We think you will be intrigued by this new finish and celebrate with us the reunion of our barrel and whiskey.Selected by former Master Distiller and Master Taster Jeff Arnett."}, {"product_id": "9a406841-1ed5-4427-b0f4-5899a2541660", "source": "jackdaniels.com", "source_url": "https://www.jackdaniels.com/whiskey/jack-daniels-bonded-tennessee-rye-whiskey", "reviewer": "Brown-Forman", "text": "The newest whiskey in the Bonded Series is a bold rye whiskey. Bottled at 100 proof, every sip is a balance of vanilla, toffee, and rye spice that brings boldness to your glass. Adhering to all the guidelines of America bottled-in-bond whiskey set out by the Bottled-In-Bond Act of 1897, this whiskey is . . . Made from a single distiller From a single distilling season Aged in a federally bonded barrel house for a minimum of 4 years Bottled at 100 proof The product depicted, including proof and package, may vary by country."}, {"product_id": "c9d3d1b7-c2c0-4f0f-9f98-f4922a2308ff", "source": "jackdaniels.com", "source_url": "https://www.jackdaniels.com/whiskey/jack-daniels-single-barrel-barrel-strength-tennessee-whiskey", "reviewer": "Brown-Forman", "text": "Selected by our Master Distiller and presented at 129 proof, this high character single barrel Tennessee Whiskey reflects the flavor imparted by our handmade, toasted and charred, American Oak barrels. Bottled a barrel at a time, Barrel Strength lifts Jack's trademark vanilla and toasted oak flavors to bold new levels for an aromatic and smooth whiskey experience, complemented by notes of sweet brown sugar that give way to hints of dark spice.Barrel Strength is available in select markets globally. The product depicted, including proof and package, may vary by country."}, {"product_id": "e5f8c167-8343-4e6b-b553-9d56328351d2", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-18-year-marriage/", "reviewer": "Buffalo Trace", "text": "This unique bourbon combines barrels from three signature mash bills that matured for eighteen years, including two different rye bourbon mash bills and our wheated bourbon mash bill. The marriage of bourbon mash bills gives this magnificent whiskey a nose of vanilla butter cake, a rich palate of caramel and cinnamon, and long finish of toasted oak, cinnamon, and hint of spearmint. A true testament to Taylor's pursuit of perfection and his dedication to push the boundaries of making whiskey, this bourbon would have made its namesake proud."}, {"product_id": "8c73ab33-c71c-4f4a-b895-28c4320e5068", "source": "castleandkey.com", "source_url": "https://castleandkey.com/products/wheated-cask-strength", "reviewer": "Castle & Key", "text": "| Couldn't load pickup availability| Refresh | Find in Stores | This product isn't available for purchase in your state. | Aged for seven years and bottled at cask strength, Castle & Key Cask Strength Wheated Bourbon delivers a bold yet beautifully balanced expression of our wheated mash bill. Bottled straight from the barrel at 108.2 proof (54.1% ABV), it offers depth, texture, and complexity without compromise.| The aroma opens with notes of oatmeal raisin cookie, vanilla frosting, baked peach, and candied pear, lifted by hints of orange peel, lilac, and soft cinnamon. On the palate, layers"}, {"product_id": "6b6a7d1a-34b7-4bb0-b16b-8c8e059236dc", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/kentucky-straight-rye-whiskey/", "reviewer": "Chicken Cock", "text": "ur Whiskey| History| Our Whiskey| Cocktails| News| Find Us| Contact| Merch| Visit Us: Bardstown| Visit Us: Louisville| Visit Us: Single Barrel Experience| Core Whiskey| Kentucky Straight Rye Whiskey| Distilled, aged, and bottled in Kentucky, Chicken Cock Kentucky Straight Rye Whiskey has a rich caramel color, with a nose of crisp apples, citrus, and toasted oak, with a wonderfully balanced palate of pear, vanilla, spearmint, and gentle white pepper.| 750ml | 45% ABV | 90 Proof| PROOF:| 90| AGE:| Minimum of 2 Years| MASHBILL:| 95% Rye / 5% Malted Barley| CHAR / TOAST:| Level 3/Medium+| $59.99|"}, {"product_id": "0e333abd-acf2-45c2-9194-f02bfc912131", "source": "clydemays.com", "source_url": "https://clydemays.com/special-reserve-bourbon/", "reviewer": "Conecuh Ridge", "text": "We bring you our Special Reserve Straight Bourbon. A select reserve of our special stock that is non chill filtered and aged 6 years in American Oak Barrels. Incredibly balanced with a smooth long finish. You get a generous amount of orchard fruits on the nose and clove and spice on the palate."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "095b12eb-a8d0-4a7a-959a-e0e176d8fe67", "source": "clydemays.com", "source_url": "https://clydemays.com/straight-rye-whiskey/", "reviewer": "Conecuh Ridge", "text": "Aged a minimum of 4 years, with floral notes, honeysuckle and apricot on the nose and spice and citrus on the palate. Finish is soft and smooth with tannins that bring out black pepper and wood spice. Best enjoyed on the rocks or served in a “Perfect” Manhattan straight up."}, {"product_id": "aa05c10b-7f74-4fa8-959a-b89dc704deda", "source": "thebar.com", "source_url": "https://www.thebar.com/en-us/products/george-dickel-bottled-in-bond-tennessee-whisky-750-ml", "reviewer": "Diageo", "text": "Bottled in Bond Tennessee Whisky | The Bar US| Skip to main content.| Shop| Brands| Recipes| Inspiration| Gifts| Engravable Bottles| Ship to| Ship to| Shop| Brands| Recipes| Inspiration| Gifts| Engravable Bottles| Home| /| Products| /| Bottled in Bond Tennessee Whisky, 750ml| George Dickel| Bottled in Bond Tennessee Whisky| There is 1 option available| 750ml| Bottled in Bond Tennessee Whisky| Check Availability| More about George Dickel Bottled in Bond Tennessee Whisky| This limited release offers a bold and balanced profile highlighted by tastes of light honey, apple, warm spices and a touch"}, {"product_id": "6580abd6-3545-4b5b-bffe-a103e29ce79f", "source": "thebar.com", "source_url": "https://www.thebar.com/en-us/products/george-dickel-rye-whisky-750-ml", "reviewer": "Diageo", "text": "Rye Whisky - Enriched with Spice | The Bar US| Skip to main content.| Shop| Brands| Recipes| Inspiration| Gifts| Engravable Bottles| Ship to| Ship to| Shop| Brands| Recipes| Inspiration| Gifts| Engravable Bottles| Home| /| Products| /| Rye Whisky, 750ml| George Dickel| Rye Whisky| There is 1 option available| 750ml| Rye Whisky| Check Availability| More about George Dickel Rye Whisky| George Dickel Rye Whisky brings depth, range and personality with spicy flavor and subtle fruit notes ending in a remarkably smooth finish.| This 90 proof Rye whisky is made from 95% rye and 5% malted barley. Fini"}, {"product_id": "7b4e0862-64f4-4d72-ace5-562c14592bf3", "source": "distillery291.com", "source_url": "https://distillery291.com/colorado-bourbon-whiskey-small-batch-aspen-wood-staves/", "reviewer": "Distillery 291", "text": "291 Colorado Bourbon Whiskey Small Batch America's native spirit, Hardmade the Colorado Way®. Notes of vanilla, cherry and spice permeate our single barrel bourbon. Made grain to barrel to bottle, paying homage to the past. 291 Colorado Bourbon Whiskey. Distilled from a bourbon sour mash, distilled in a copper pot still, aged in American White Oak deep char barrels and finished with toasted Aspen Staves. San Francisco World Spirits Competition Double Gold winner. American Whiskey Master award 2019. 100 proof / 50% ABV Bottle size: 750ml Please note: This 291 Colorado Whiskey product may take up to 2 weeks for ground delivery Bottle size: 750ml Please Drink Responsibly. This produc"}, {"product_id": "bbcde06a-4537-4341-918c-3daa14070be3", "source": "distillery291.com", "source_url": "https://distillery291.com/colorado-straight-rye-whiskey-barrel-proof/", "reviewer": "Distillery 291", "text": "291 Colorado Straight Rye Whiskey Loads of rich caramel and toffee up front on the nose. Leather and pipe tobacco add an earthiness, while cinnamon and clove balance it out with some spice. Hints of toasted oak and aspen round out the nose. The palate is viscous, with the clove, toffee, tobacco, and toasted oak at the forefront. There is a warming black pepper note with the return of the caramel for the long, pleasant finish. This is an assertive and spice forward rye, and yet somehow, at the same, a soft and sweet rye. Enjoy two of our newest tasting room releases – 291 Colorado Straight Rye Whiskey and 291 Colorado Straight Bourbon Whiskey. Matured in deep-charred, new American white"}, {"product_id": "78961dd3-d72b-465b-98cc-2840ceb40746", "source": "distillery291.com", "source_url": "https://distillery291.com/colorado-straight-bourbon-whiskey-barrel-proof/", "reviewer": "Distillery 291", "text": "Straight Bourbon Whiskey Barrel Proof The nose is full of assorted stone fruits such as apricots, nectarines, and peach cobbler, along with floral potpourri. Herbal tea, mint, and black pepper add spiciness and depth to the nose, while cedar and aspen dance around on the edges. The stone fruits are the first to greet the palate, along with the mint and herbal tea. The texture is surprisingly soft, especially given the high proof. The clove and black pepper spices quickly move in as it transitions to a lively finish with apricots, aspen, and floral notes. Enjoy two if our newest tasting room releases – 291 Colorado Straight Rye Whiskey and 291 Colorado Straight Bourbon Whiskey. Matured"}, {"product_id": "7bd7be37-823e-4b10-8aaa-2f0b8927e9f3", "source": "distillery291.com", "source_url": "https://distillery291.com/product-291-ram-skull-colorado-bourbon-whiskey/", "reviewer": "Distillery 291", "text": "“BIG HORN IS DEAD! LONG LIVE RAM SKULL!” After a cease and desist letter, 291 Big Horn is dead… but not gone. Out from it's grave comes 291 Ram Skull Colorado Bourbon Whiskey. Still the same recipe, the one that was first created by mistake when a double dose of rye was accidentally added to a bourbon mash. Still finished with aspen staves. Still a delicious, complex bourbon that strikes a balance between our Colorado Bourbon Whiskey and our Colorado Rye Whiskey. And still released in limited annual batches. 291 Big Horn is dead! Long Live 291 Ram Skull! Tasting Notes: Dried stone fruits, cinnamon and nutmeg spices, Virginia tobacco, butterscotch candies, marshmallow Release Date:"}, {"product_id": "a7872a4f-862d-44d0-90be-d14172075fb2", "source": "distillery291.com", "source_url": "https://distillery291.com/product-291-all-rye-malt-colorado-whiskey/", "reviewer": "Distillery 291", "text": "Crafted with 100% rye malt and finished with toasted aspen wood staves, this limited-edition whiskey offers rich, complex flavors, colors, and mouthfeel. It represents what 291 Colorado Whiskey is known for– Rugged, Refined, and Rebellious®️ whiskey, now coming forth in a single malt expression. 291 All Rye Colorado Whiskey Batch #3 promises to be an instant favorite among whiskey enthusiasts, offering a unique flavor profile with notes of assorted dried stone fruits, sandalwood, butterscotch, black pepper, cedar, and cinnamon toast. “We were inspired to create the addition to our line-up after the success of 291 E Batch 3, one of our first single malt experiments,” said Michael Myers, CE"}, {"product_id": "d8c4e5d7-8cd8-4270-a5a9-57c002c261bc", "source": "distillery291.com", "source_url": "https://distillery291.com/bad-guy-bourbon-whiskey-10/", "reviewer": "Distillery 291", "text": "“The Bad Guy” Originally made as an experimental batch, Bad Guy is a wheated four-grain bourbon. It was our first award-winning bourbon whiskey and one of our most bold, rich, and complex whiskeys. Distilled from a mash of corn, malted wheat, malted rye and beech smoked barley malt, this whiskey is heavier on the sweet side despite its high proof. Always presented at barrel proof. Tasting notes of marzipan, dried apricot, cinnamon, clove, and earl grey tea, eucalyptus and toffee. Always presented at barrel proof. Please note: This 291 Colorado Whiskey product may take at least 2 weeks for ground delivery. Bottle size: 750ml ABV: 61.6% Alc. /123.2 proof Please Drink Responsibly"}, {"product_id": "34811d68-ca94-4c32-93e2-fa0c45411ec2", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/fruit-odyssey", "reviewer": "Doc Swinson's", "text": "Straight Bourbon Whiskey Finished in Ruby Port Casks| Fruity and aromatic ruby port compliments the rich caramel and vanilla flavors coming from the bourbon. An odyssey of aromatics arise from your glass; fresh raspberries on a dewy summer morning, turkish rose cookies, sweet cinnamon, and a subtle caramel oakiness to round it out. | This is a bourbon journey you won't want to leave. |"}, {"product_id": "0d6ee967-2d46-4f4f-9b07-e164807a8d65", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/funky-drummer", "reviewer": "Doc Swinson's", "text": "RYE FINISHED IN Jamaican Rum CaskS| Doc Swinson's Funky Drummer | is a bold, electrifying rye whiskey that hits differently than most rye's finished in rum casks. Driven by high-ester Jamaican rum casks that richens the spice profile with tropical fruit funk, deep molasses tones, and explosive aromatics. | THE STORY BEHIND THE SPIRIT| Inspired by our love of rye and tiki drinks. Funky Drummer celebrates improvisation, complexity, and tradition in the rum world. We selected 2 rye whiskeys with sp"}, {"product_id": "e3f25840-60c6-43ed-8dca-a68acc2998a5", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/golden-hour", "reviewer": "Doc Swinson's", "text": "Rye Whiskey Finished in RUM & Port Casks| There are few natural compliments in this world that just go together. The spiciness of rye whiskey perfectly complimented by rich and juicy elements of decades old port casks. | This juxtaposition is then perfectly tied together with a hint of sugar cane and citrus from the rum casks. In this instance, the wildness of the rye whiskey is almost tamed, a refinement allowing for the unraveling of identifiable notes from brown sugar, banana bread, raspberry"}, {"product_id": "e373679a-aafb-4c6e-8c14-196494189c57", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/moscatel", "reviewer": "Doc Swinson's", "text": "Straight bourbon whiskey finished in MoscAtel Casks| When Happenstance Meets Award-Winning Bourbon| These decades-old Moscatel casks were found in the Setubal Region of Portugal and soon became home to Doc Swinson's blend of two five-year bourbon whiskeys. Knitting together flavors of sweet caramel and stone fruits from Doc Swinson's Blender's Cut Bourbon with notes of wildflower honey, apricots, and seasoned oak creates a flavor experience like no other.| Limited release| Batch 23-0007|"}, {"product_id": "43d36d07-6c86-4f72-8911-5d21f32b96a7", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/samba", "reviewer": "Doc Swinson's", "text": "Rye Whiskey Finished in Rum cask solera & Brazilian Amburana casks| Samba is a fusion of spice, sweetness, and exotic wood influence. Originally built from a blend of 2 rye whiskey mash-bills, balancing sweet corn with spicy rye profiles aged a minimum of 7 years then entered our Solera system built with rum casks from 4 distilleries. | This develops underlying tones of tropical fruits and citrus for a minimum of 2 years, picking up bright citrus and tropical fruit notes. This Solera Rye then is"}, {"product_id": "a19d0198-16eb-4dad-9fb9-1dbfd01f0fbd", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/summer-retreat", "reviewer": "Doc Swinson's", "text": "Straight Rye Whiskey Finished in White Port Casks| Let your senses take you on a retreat with rye whiskey aged in white port barrels. A port style rarely found in north america, it's similar to a vinho verde with fresh floral notes and a nice acidity that compliments the robust sweet and spicy profiles of the rye whiskey.| Profiles of toasted almonds, and and zesty orange marmalade, leaving a vibrant impression on the palate. Delight in the subtle acidity enhancing the whiskey's freshness. |"}, {"product_id": "d97d25c4-7f2c-4714-8880-eba1fba86e3d", "source": "drinkmhs.com", "source_url": "https://drinkmhs.com/spirits/fireside-bottled-in-bond", "reviewer": "Mile High Spirits", "text": "Mile High Spirits' first bottled-in-bond bourbon and a workhorse of the Fireside lineup. Aged at least four years in our federally bonded Denver rickhouse, distilled in a single season by a single distiller, and bottled at exactly 100 proof. Built on our signature 70% corn / 20% rye / 10% chocolate malted barley mashbill, it pours yellow gold and walks the line between traditional bourbon and something distinctly ours, fresh oak, grain, light baking chocolate, and vanilla on the nose, then a palate of pine needle, vanilla, oak, rye spice, mint and pie dough, finishing on rye, leather, and a he"}, {"product_id": "8ab9afeb-5fac-4f67-a1f7-51e20ef75964", "source": "drinkmhs.com", "source_url": "https://drinkmhs.com/spirits/wheated-bottled-in-bond", "reviewer": "Mile High Spirits", "text": "A core release from Mile High Spirits, a wheated bourbon built on 70% Colorado sweet corn, 20% wheat, and 10% malted barley, aged at least four years and bottled in bond at 100 proof. Dark caramel in the glass, with a nose of chocolate raspberry, prune, brown sugar, pomegranate molasses, and light clove. The palate runs molasses, stone fruit, blackberry, and cinnamon spice, then finishes on apple, sweet oak, pecan pie, mixed berry jam, and a touch of leather and clove. Breaking Bourbon: \"Fireside Bottled in Bond Wheated Bourbon consistently delivers a flavorful and expressive sip, all at an ac"}, {"product_id": "a75ef8b6-f6b5-4eee-b559-68654370a8e8", "source": "drinkmhs.com", "source_url": "https://drinkmhs.com/spirits/fireside-hazmat", "reviewer": "Mile High Spirits", "text": "A single-barrel bourbon pulled at full cask strength, high enough that the FAA classifies it as a hazardous material and bans it from passenger aircraft. Hence the name. Deep amber in the glass, with a nose of pine, vanilla custard, passion fruit, and unmistakable heat. The palate is chewy and dense: sweet oak, barrel char, pine bark, and rich, deep wood. The finish develops spicy heat, then turns sweet, caramel, caramel corn, seasoned oak, and vanilla custard, lingering long. Breaking Bourbon: \"Bursting with flavor, this hazmat proof bourbon from Mile High Spirits is equal parts unique and fl"}, {"product_id": "fc410f81-d88d-4e28-892e-be8d49f3b6cc", "source": "drinkmhs.com", "source_url": "https://drinkmhs.com/spirits/strato-whiskey", "reviewer": "Mile High Spirits", "text": "Strato is the world's first bourbon to be aged in the stratosphere. Distilled from our signature Fireside mashbill (70% corn, 20% rye, 10% malted barley) and aged 4 years 8 months in Denver, a 3-gallon barrel was sealed and launched on a World View craft from Page, Arizona on July 15, 2021, climbing to 106,627 feet, weathering a 184°F temperature swing and atmospheric pressure crashing from 1,000 to 9 millibars before returning to Earth for another 1 year, 4+ months in oak. Dark bronze in the glass, with charred oak, burnt caramel, rye grain, nougat, leather, and a long cinnamon-and-vanilla-be"}, {"product_id": "39a9a5ee-6efa-4257-ac54-e379ab162f3a", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-11-ruby-rye-springs", "reviewer": "Four Gate Whiskey Company", "text": "BATCH 11 RUBY RYE SPRINGS Ruby Rye Springs is Four Gate Whiskey Company's third presentation of the same underlying 7-year old Straight Rye Whiskey from Indiana following River Kelvin Rye (Batch 7) and Split Stave™ by Kelvin (Batch 10). This latest release showcases the citrus and spice characteristic of the sourced base spirit while adding a fruity sweetness from 42 days extra aging in Ruby Port-Rum Casks. The secondary casks originally were originally used to mature ruby port, a fortified wine from Portugal in which the wine is removed from barrels and stored in tanks to prevent further aging, leaving the resulting product sweeter and brighter on the palate than other styles of port wine."}, {"product_id": "3e84f9fa-8cee-4fcf-be64-a55f88bf4083", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-18-saint-charente", "reviewer": "Four Gate Whiskey Company", "text": "BATCH 18 SAINT CHARENTE Batch 18 is a 7 year Kentucky Straight Bourbon Whiskey finished in French Cognac casks. Named for the Charente river that flows through the Cognac region of France, St. Charente is a whiskey that smells of baking spices, cooked apples and orchard fruits, and sweet cinnamon. There were 2,365 bottles released at 119.2 Proof. Mash Bill: 75% Corn, 21% Rye, 4% Malted Barley State of Distillation: Kentucky Non-Chill Filtered 119.2 Proof 2,365 Bottles MSRP: $199"}, {"product_id": "37678c6c-3ccc-4ecf-9ae6-1b8d040efb49", "source": "greenriverwhiskey.com", "source_url": "https://greenriverwhiskey.com/full-proof-bourbon/", "reviewer": "Green River", "text": "117.3 proof)| Green River Full Proof Bourbon is the same rye-forward Kentucky straight bourbon you know, released at full strength. Hand-blended from select barrels and bottled at 117.3 proof, this barrel-strength bourbon is made for those who want their whiskey uncut and uncompromised. Aged onsite in century-old warehouses at Green River Distilling Co. in Owensboro, KY, it delivers bold notes of spice, vanilla, caramel, and dark fruit with a rich, lingering finish. Best enjoyed neat or over a single large cube.| Find Near you| Mash Bill| 70%| kentucky grown corn| 21%| rye| 9%| Malted Barley|"}, {"product_id": "9b866716-c84a-4ae0-b5de-5a78cd96b08a", "source": "greenriverwhiskey.com", "source_url": "https://greenriverwhiskey.com/kentucky-straight-rye/", "reviewer": "Green River", "text": "who want something bold. Crafted with a high-rye mash bill and bottled at 95 proof, this Kentucky straight rye whiskey pours a rich auburn with polished mahogany depth. The nose brings bright citrus, fresh mint, and rye spice layered over subtle sweetness. On the palate, that spice carries through with warmth and purpose, leading to a clean, slightly herbal finish with soft oak tones. Distilled and bottled at Green River Distilling Co. in Owensboro, KY, this is a Kentucky rye whiskey that earns its place next to the best in the category.| Find Near you| Mash Bill| 95%| rye| 5%| malted barley|"}, {"product_id": "5f3b3800-1b49-4ba0-ba87-d0fc1ca3bd30", "source": "greenriverwhiskey.com", "source_url": "https://greenriverwhiskey.com/single-barrel-wheated/", "reviewer": "Green River", "text": "ost personal expression in the Green River lineup. Each bottle comes from a single, hand-selected wheated bourbon barrel, aged over five years in the historic warehouses at Green River Distilling Co. in Owensboro, KY. Because no two barrels age identically, proof varies by barrel, giving each release its own distinct character. This cask-strength wheated bourbon delivers soft notes of orange, apricot, cinnamon, and toffee with a honeyed, lasting finish. A true single-barrel experience for the collector and the curious alike.| Find Near you| Mash Bill| 70%| Corn| 21%| WHEAT| 9%| malted barley|"}, {"product_id": "33b0b2b8-8d64-4a08-bba4-8ad4c6846b3d", "source": "greenriverwhiskey.com", "source_url": "https://greenriverwhiskey.com/wheated-full-proof-bourbon/", "reviewer": "Green River", "text": "Green River Wheated Full Proof Bourbon takes the softness and sweetness of Green River Kentucky Straight Wheated Bourbon and releases it at barrel strength. Hand-selected wheated barrels are blended and bottled at approximately 109.3 proof, with each batch varying slightly. Crafted at Green River Distilling Co. in Owensboro, KY, this wheated barrel-strength bourbon delivers rich caramel, vanilla, citrus, and baking spice with a soft, full finish and just enough proof heat to remind you it's a serious whiskey.| Find Near you| Mash Bill| 70%| kentucky grown corn| 21%| WHEAT| 9%| Malted Barley|"}, {"product_id": "702fb038-4fdb-43c6-92d3-6b6a33c0488e", "source": "heavensdoor.com", "source_url": "https://www.heavensdoor.com/straight-rye-whiskey", "reviewer": "Heaven's Door", "text": "e Straight Rye Whiskey is aged for 6-8 years, blended to ensure consistent maturity has been reached and then finished in sherry casks, boasting a sweet, fruity characteristic that is distinctively rich and refined with notes of dried fruits and a delicate, spicy finish.| Sherry is a drier aperitif, which complements our 100% rye mash with notes of leather, nutmeg, and tobacco. Typically, we finish for up to six months, however, weather and seasons play a momentous roll in in aging and extraction, requiring our blenders to continually curate our spirits with precision.| ​| Ⓤ Certified Kosher|"}, {"product_id": "7f79b3ad-8493-4732-acc7-0449d19ff07e", "source": "highwest.com", "source_url": "https://highwest.com/pages/limited-releases", "reviewer": "High West", "text": "The Prisoner's Share is a limited-release blend of straight bourbon and rye whiskeys, aged between 4–12 years and finished in The Prisoner Red Blend wine barrels to create a deeply layered, wine-influenced profile. Bottled at 51% ABV, it balances bold structure with refined nuance, crafted for savoring slowly rather than rushing through the glass.​ On the nose, it opens with vibrant pomegranate kernels and cranberry biscotti, drifting into pecan brittle and bright orange zest, all framed by cinnamon bark, light roast espresso, and a subtle impression of tanned leather from a cedar closet. The"}, {"product_id": "e3b2cf19-2232-47a6-9c84-1c3101cf3330", "source": "ship.highwest.com", "source_url": "https://ship.highwest.com/products/campfire", "reviewer": "High West", "text": "High West Campfire is the world's finest blend of straight rye whiskey, straight bourbon whiskey, and blended malt Scotch whiskey. A very unusual, distinctive, and delicious pour that brings together both old and new world whiskey traditions. Tastes of classic peat smoke give way to chai spice, orange zest, English toffee, leather and dark chocolate. Campfire is High West's ode to starry nights around the fire with friends."}, {"product_id": "40ae7075-0ae0-4e68-8ec6-1957304767eb", "source": "ship.highwest.com", "source_url": "https://ship.highwest.com/products/double-rye", "reviewer": "High West", "text": "Our distinctive Double Rye embodies a harmonious balance of bold rye spice with bright botanical notes that simultaneously showcase layers of freshness and complexity. A blend of column and pot-still whiskies, aged a minimum of two years. Curated to highlight the wonderful, bold spice character that comes from high rye whiskies as well as a refreshing botanical brightness. A unique and balanced flavor profile of cinnamon, gingersnaps, juniper, mint sprigs, and fresh wildflower honey. Blended to be boldly sipped, stirred, and savored."}, {"product_id": "235b9927-74a7-4558-a7db-9a5cc6316748", "source": "horsesoldierbourbon.com", "source_url": "https://horsesoldierbourbon.com/products/barrel-strength-straight-bourbon-whiskey", "reviewer": "Horse Soldier", "text": "Premium Barrel Strength Bourbon Whiskey Horse Soldier Bourbon Our award-winning Reserve Barrel Strength Bourbon Whiskey is extraordinarily complex with notes of butterscotch, oak, and stone fruits. This barrel strength “wheated” bourbon is made from small batches of meticulously blended mature bourbon and non-chill filtered to provide a full-bodied and decadent finish."}, {"product_id": "8054bed3-2c22-450e-a5d7-1e7f1ce30a66", "source": "ourwolfspirit.com", "source_url": "https://ourwolfspirit.com/products/punchers-chance-bourbon-the-undisputed", "reviewer": "IJW Whiskey Company", "text": "Puncher's Chance American Whiskies are built on the tenet of \"perfect balance\" - where the flavors and aromas that comprise a memorable whiskey, such as sweet, spicy, fruity, floral or savory, sing in resolute harmony, with none outshining another. Crafted from sourced five- and six-year-old Kentucky Straight Bourbons from IJW Whiskey Company. The brand name \"Puncher's Chance\" is a boxing reference, denoting that almost anyone can deliver a knockout punch, no matter what the odds are, particularly if that punch is delivered with perfect balance. Our Single Barrel Selection: These are finely re"}, {"product_id": "d6df3a1c-29d9-473c-8bf4-d8738bd94bc3", "source": "ourwolfspirit.com", "source_url": "https://ourwolfspirit.com/products/the-distance-12-year-tennessee-straight-bourbon", "reviewer": "IJW Whiskey Company", "text": "It takes courage and perseverance to make it to the 12th Round of a fight. That's why it's called “the distance” round. Many try, few succeed. Those few deserve Puncher's Chance® 12-Year-Old Tennessee straight bourbon whiskey — a bourbon crafted with heart, honor, and then aged to perfection. Classic notes of big vanilla, toasted oak aroma and a hint of cedar complement complex apricot and orange peel evolutions in the early palate, followed by flavors of tobacco and leather. The finish, just slightly sweet, is robust and warming. If you have a passion worth fighting for and can go The Distanc"}, {"product_id": "4383405b-6551-478b-92c5-6ae448982688", "source": "ezrabrooks.com", "source_url": "https://ezrabrooks.com/whiskey/ezra-90/", "reviewer": "Lux Row", "text": "Caramel and vanilla with hints of spice and chocolate, completed with a"}, {"product_id": "3336e0f4-387e-4a9e-8143-8e27923e5e98", "source": "ezrabrooks.com", "source_url": "https://ezrabrooks.com/whiskey/ezra-99-rye/", "reviewer": "Lux Row", "text": "Hints of chocolate, leather, vanilla, and spicy grains, balanced by slightly sweet and oaky tones."}, {"product_id": "c165608c-0be4-447e-a25a-45c43e29cdd9", "source": "ezrabrooks.com", "source_url": "https://ezrabrooks.com/whiskey/ezra-99/", "reviewer": "Lux Row", "text": "Smooth and drinkable with hints of caramel, vanilla, chocolate, and spice."}, {"product_id": "85174f78-bfcd-4281-af59-8bcd776efe94", "source": "ezrabrooks.com", "source_url": "https://ezrabrooks.com/whiskey/old-ezra-7-straight-rye-whiskey/", "reviewer": "Lux Row", "text": "Slightly sweet and oaky tones with hints of vanilla and honey. Finishes with a warm touch of spice and tobacco"}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "63958edb-31d0-4710-985c-4322cd0d4c20", "source": "luxrowdistillers.com", "source_url": "https://luxrowdistillers.com/david-nicholson/", "reviewer": "Lux Row", "text": "Rich scents of honey and butter are followed by subtle hints of vanilla and oak. Exceptionally smooth to start, followed by woody and smoky tones Long, warm finish with a touch of spice"}, {"product_id": "343d11d6-fe84-42c1-a807-75a7ca314f04", "source": "luxrowdistillers.com", "source_url": "https://luxrowdistillers.com/david-nicholson/", "reviewer": "Lux Row", "text": "Vanilla, honey with toasted, oaky spice Smooth, spicy, sweet honey and just a hint of chocolate Toasty, full-bodied, with a nice long finish"}, {"product_id": "9126804c-1dbc-4ade-bd76-b66c31483cfc", "source": "luxrowdistillers.com", "source_url": "https://luxrowdistillers.com/lux-row-double-barrel/", "reviewer": "Lux Row", "text": "Oak, caramel, and vanilla Caramel, citrus, vanilla, and cinnamon Velvety smooth, with a mellow oak finish"}, {"product_id": "953e5b1c-9445-4717-8fc3-e5a76c102cb9", "source": "luxrowdistillers.com", "source_url": "https://luxrowdistillers.com/lux-row-double-barrel/", "reviewer": "Lux Row", "text": "An aromatic bouquet of dried figs and dates Flavors of grape syrup and candied fruit Hints of spice, roasted coffee, and dark chocolate"}, {"product_id": "9ac07d38-c4b8-4b29-a7ec-d8c872374245", "source": "rebelbourbon.com", "source_url": "https://rebelbourbon.com/whiskey/kentucky-straight-bourbon/", "reviewer": "Lux Row", "text": "Honey and butter hit the nose. Then, traces of raisin and a warm spice finish kick things up a notch."}, {"product_id": "8f2d236a-95a3-4dfd-8236-8a2ef2ef783d", "source": "rebelbourbon.com", "source_url": "https://rebelbourbon.com/whiskey/rebel-100-aged-6-years/", "reviewer": "Lux Row", "text": "This Rebel Kentucky Straight Bourbon Whiskey is aged a full six years and bottled at 100 proof for a rich & rebellious flavor. Starts with dark fruits, followed by citrus and oak. It boasts a velvety smooth finish with a hint of spice."}, {"product_id": "7be899f2-786e-4d40-a346-a7654e9b6997", "source": "rebelbourbon.com", "source_url": "https://rebelbourbon.com/whiskey/small-batch-reserve/", "reviewer": "Lux Row", "text": "A standout honey with vanilla and caramel flavor, with notes unique to the original time-honored wheated bourbon recipe created in 1849."}, {"product_id": "21d97dc5-84d2-4919-8788-b0e6ac0880c8", "source": "michters.com", "source_url": "https://michters.com/bombergers-declaration/", "reviewer": "Michter's", "text": "Bomberger's Declaration Kentucky Straight Bourbon honors the legacy of the former distillery known as Bomberger's in the 1800's and later as Michter's in the 20th Century. Please join us in toasting and celebrating American Whiskey History with this outstanding small batch 108 proof Kentucky Straight Bourbon. This 2026 release of Bomberger's Declaration Kentucky Straight Bourbon features the whiskey's hallmark Chinquapin oak, coupled with the addition of Hungarian oak, thereby creating an intriguing, rich chocolate decadence around the cherry and spice attributes characteristic of Chinquapin. Both types of oak were naturally seasoned and air dried for three years with a custom toast and char. The result is a bold, expressive journey of a complex cherry profile underscored by baking spice, toasted pecans, butter toffee, and luxurious layers of chocolate, all supported by a silky texture"}, {"product_id": "04c0bbd0-64ac-4131-a163-6871e1b831f5", "source": "michters.com", "source_url": "https://michters.com/toasted-barrel-finish-rye/", "reviewer": "Michter's", "text": "In its continued pursuit of offering the greatest American whiskey, Michter's is proud to release the 2026 edition of its US ★ 1 Toasted Barrel Finish Rye. Beginning with fully matured US ★ 1 Kentucky Straight Rye at barrel strength, the whiskey is aged for an additional period in a second custom barrel made from 24-month air-dried wood and toasted to exacting specifications. The result is a remarkably rich, complex rye with notes of toffee, black walnut, and cherry complemented by pronounced spice and beautifully rounded oak. The average strength of the barrels in this limited release is 109.1 proof."}, {"product_id": "a756319b-3e52-4b5a-bb1e-39b426780b9b", "source": "middlewestspirits.com", "source_url": "https://middlewestspirits.com/spirits/whiskey/mws-oloroso-wheat-whiskey/", "reviewer": "Middle West Spirits", "text": "It's crafted from Ohio-grown soft red winter wheat and aged in American white oak barrels. The mature wheat whiskey is then transferred to Oloroso Sherry casks, where it acquires rich, nutty notes of black cherry, dark chocolate, and raisins."}, {"product_id": "56b087a8-fabd-41a0-93a3-63ab669e1ffc", "source": "oldelk.com", "source_url": "https://www.oldelk.com/cask-finish-series", "reviewer": "Old Elk", "text": "Old Elk Cognac Cask Finish Straight Wheat Whiskey begins with our Straight Wheat Whiskey, aged for six years before receiving an additional six months to one year of finishing in carefully selected French Limousine Cognac casks. The wheat whiskey's delicate fruit and spice are complemented by rich layers of dark fruit, honeycomb, caramel and orange."}, {"product_id": "69c006dc-74bb-4aea-908f-12e003bb58fb", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/straight-bourbon-2026", "reviewer": "Pinhook", "text": "2026 Straight Bourbon Aged more than 4 years, the 2026 vintage of Pinhook Bourbon showcases a vibrant nose of red apple skin, leather, butterscotch, and cinnamon, and leads to a lively palate of baked apple, candied almond, rosewater, and white pepper. -->"}, {"product_id": "e9f85bda-d95b-4976-b49a-4258820f3cf2", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/straight-rye-2026", "reviewer": "Pinhook", "text": "2026 Straight Rye Aged more than 4 years, the 2026 vintage of Pinhook Rye showcases a bright nose of green apple, mint, candied clove, and vanilla, and leads to a decadent palate of baked pear, black licorice, caramel, and cinnamon. -->"}, {"product_id": "8ce4397a-b5cf-4165-9b59-7821038841d5", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/high-proof-rye", "reviewer": "Pinhook", "text": "2022 High Proof Rye Rye Munny Bottled just under cask strength, our 2022 High Proof Rye opens with a soft and fragrant nose of orange blossom , honeysuckle , green apple , and baking spice , leading to a rich palate of walnuts , dates , spiced caramel , and white pepper ."}, {"product_id": "fad1cb11-5352-44c3-87fe-37e4b1f1a175", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/cask-strength-bourbon", "reviewer": "Pinhook", "text": "2026 Cask Strength Bourbon The 2026 vintage of Pinhook's Cask Strength Bourbon showcases a bright nose of dried mango, butterscotch, cedar, and white pepper, and leads to a vibrant palate of maraschino cherry, toffee, almond, and candied cinnamon. -->"}, {"product_id": "4d147dd3-9896-4b13-abc6-043ac6b350d1", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/rye-humor-cask-strength", "reviewer": "Pinhook", "text": "2018 Cask Strength Rye Rye Humor Proofed at 114, this straight rye whiskey's deep and dense aromas of dark chocolate , candied black licorice and vanilla extract set the stage for robust flavors of raisins , tobacco , cinnamon stick and sarsaparilla ."}, {"product_id": "2921e4e5-71dd-4575-b9f1-9501ecdffcf2", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/vertical-series-bourbon-11-year", "reviewer": "Pinhook", "text": "2026 Vertical Series Bourbon 11 Year Bourbon War—11 Year Blended from just 62 barrels, this year's Vertical Series Bourbon showcases a rich nose of burnt orange peel, molasses, white pepper, and cedar, and leads to a coating palate of ripe strawberry, crème brûlée, toasted almond, and candied cinnamon. This product is available to reserve for preorder. Preorder begins 9.1.26 and is expected to ship mid-October."}, {"product_id": "3dbf3b4f-e384-453c-acfd-85d1d108af54", "source": "pinhookbourbon.com", "source_url": "https://pinhookbourbon.com/products/collaboration-series-no-5", "reviewer": "Pinhook", "text": "2026 Collaboration Series No. 5 by Donald Link and Stephen Stryjewski Pinhook was founded with the ethos of sourcing great barrels of whiskey and taking a creative and unique approach to blending and proofing. The Collaboration Series reflects our commitment to exploring the ever growing craft whiskey movement and “pinhooking” barrels based on experience, quality, a little patience, and a bit of luck. This edition showcases a rich nose of baked apple, nutmeg, caramel, and cedar, and leads to a warm palate of cherry, clove, brown sugar, and leather The Collaboration Series No. 5 is available to"}, {"product_id": "07a1334e-84ce-4837-9c94-63721da7cb77", "source": "rabbitholedistillery.com", "source_url": "https://www.rabbitholedistillery.com/products/follesrunn-1-375", "reviewer": "Rabbit Hole", "text": "| ONLY | 71| REMAIN FOR ONLINE SALES!| Our Distillery Series is our vehicle to bringing you whiskey you've never experienced before. Introducing our 2nd installation, Follesrunn Rye Whiskey Finished in Cognac Casks.| Named for the \"Runners\" of the classic cognac grape, \"Folles Blanche\" - it might be a good idea to do some running of your own down to our distillery to get your hands on it.| Aroma:| Fig, Blossom, Pear, Allspice, Mint, Licorice, Banana, Vanilla, Custard, Nutmeg, Maple Syrup, Toasted Almond, Apple| Palate:| Black Pepper, Allspice, Custard, Wine, Floral, Prune, Fig, Berry, Dried Fr"}, {"product_id": "48eec957-f43b-4127-9edc-3ebf295a4eaa", "source": "rd1spirits.com", "source_url": "https://rd1spirits.com/pages/finished-with-brazilian-amburana-wood", "reviewer": "RD1 Spirits", "text": "The best of baking spices – apple cinnamon, nutmeg and light brown sugar – come alive on the nose and are followed by pine, vanilla, peaches and apricots. Flavor galore with spice cake, and ginger snaps in a rich mouthfeel. Try a drop of water to open up hints of herbal black tea, dark berry jam and pineapple pepper. Finish is long and warm, and ends with allspice and sweet oak."}, {"product_id": "055bd779-e49c-42fb-9554-0b0c5d64a61c", "source": "rd1spirits.com", "source_url": "https://rd1spirits.com/pages/double-finished-in-oak-and-maple-barrels", "reviewer": "RD1 Spirits", "text": "An undeniable burst of maple and butterscotch on the nose followed by lightly toasted caramel, roasted pecans and paprika. Its flavor boasts a delicate dance of maple goodness and black peppercorn spice. The finish is long, smooth and spicy with a light accent of toasted caramel at the end. Try this in an Old Fashioned but skip the simple syrup and just add more of this bourbon."}, {"product_id": "11fde78d-10e7-4cfe-9096-9bb44d8a8b73", "source": "rd1spirits.com", "source_url": "https://rd1spirits.com/pages/ten-year-amburana-finish", "reviewer": "RD1 Spirits", "text": "The flavors from the depths of the rickhouse are brightened by the dynamic yet delicate Amburana character that draws you in further. On the nose, spiced apple and honey come alive. Upon sipping, allspice mixes with oak and black pepper notes, later transcending into a warm caramel sweetness with hints of ripe peach and baked fruit. Notes of aged oak, tobacco, leather and apple linger with whispers of earth and anise."}, {"product_id": "7ccfbfc0-0969-4689-9fa7-7b517d020ad3", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/rye/", "reviewer": "Redemption", "text": "BRING ON THE COMPLEXITY Our signature rye whiskey is a deliciously satisfying exploration of rye's complexity and distinct spiciness. Made with a no-holds-barred rye content of 95% — well past the 51% required to be called a rye whiskey — this whiskey showcases the impressive range of flavors rye can bring to the mix, from oak and florals to citrus tones and even mint. 92"}, {"product_id": "42601539-0d67-423a-892c-6b69a8d97b36", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/36-year-old-bourbon/", "reviewer": "Redemption", "text": "IF YOU EVER HAVE A CHANCE TO TASTE THIS, TAKE IT One of the world's most exclusive whiskey experiences, this bourbon's numerous pleasures begin with its wood topper, into which is embedded a penny from 1978—the year it was distilled. And it is definitely a lucky penny for those fortunate enough to possess one, because there are only 18 in existence. From beginning to end, this whiskey is a revelation. It begins with aromas of leather, grilled meat, cherry wood, and cigar box. Upon sipping, you'll discover dried orange and cinnamon mingling with sweet smoke. It cascades into a medium-length finish with lingering notes of cherry wood and citrus 97.6"}, {"product_id": "7eac6b0e-d558-4452-8609-bc9570eca871", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/ryes/old-rickhouse-rye-whiskey/", "reviewer": "Starlight", "text": "Recipes| Single Barrel Program| Distiller's Club| Where to Buy| Book a Tour| Starlight Distillery | Old Rickhouse Rye Whiskey | 92 Proof| Our Old Rickhouse Rye Whiskey starts with sweet mash fermentation and distilled in our copper pot stills, this straight small batch Rye Whiskey is aged in new American Oak barrels for a minimum of 4 years, then blended and bottled at 92 proof. The result is a sustainable small batch rye whiskey displaying distinctive hints of sweet caramel and vanilla. The prominent characteristics of rye exhibiting classic spice notes which shine through, making for a long smooth finish.| Buy Online| Find in a Store| Select one of our online dealers| (opens in new tab)|"}, {"product_id": "a73b4273-0393-428b-a660-a88c3adfc7ab", "source": "lexingtonbrewingco.com", "source_url": "https://lexingtonbrewingco.com/whiskey-spirits/town-branch/town-branch-wheated-bourbon-whiskey", "reviewer": "Town Branch", "text": "Whiskey & Spirits » Town Branch » Town Branch® 6yr Wheated Bourbon Whiskey Town Branch® 6yr Wheated Bourbon Whiskey 2026-08-27T13:06:25-04:00 Town Branch® 6YR WHEATED KENTUCKY STRAIGHT BOURBON WHISKEY Town Branch® 6yr Wheated Kentucky Straight Bourbon Whiskey delivers the bold, timeless character of Kentucky bourbon, softened and gently sweetened by the inclusion of wheat in the mash bill. The result is a distinctive drinking experience that sets it apart from traditional Kentucky straight bourbons. First distilled in 2017 and released in 2026, this wheated bourbon is aged for a minimum of six years before bottling. It offers a rich tasting profile of butterscotch, honey, biscuit, and oak, layered with notes of baked apple and warm spice."}, {"product_id": "1f30b8cc-5c47-40a2-af81-12d97505506f", "source": "lexingtonbrewingco.com", "source_url": "https://lexingtonbrewingco.com/whiskey-spirits/town-branch/town-branch-sherry-cask-finished-bourbon-whiskey", "reviewer": "Town Branch", "text": "Whiskey & Spirits » Town Branch » Town Branch® Sherry Cask Finished Bourbon Whiskey Town Branch® Sherry Cask Finished Bourbon Whiskey 2026-01-21T13:58:08-05:00 Town Branch® Sherry Cask Finished Bourbon Whiskey Town Branch® Sherry Cask Finished Bourbon is a seamless blend of Bourbon from two unique sherry finishes – a bourbon blend finished in Oloroso sherry barrels married with several unique single barrel bourbon expressions individually finished in Oloroso sherry barrels. The result is a unique expression of Town Branch Bourbon with flavors of sherry interwoven, with fig, vanilla and roasted, dry nuts providing pronounced complexity and an exceptionally smooth finish. Product Finder Lexington Brewing and Distilling Co."}, {"product_id": "d768f8ba-6cc9-4d58-bca8-5127922c7b33", "source": "lexingtonbrewingco.com", "source_url": "https://lexingtonbrewingco.com/whiskey-spirits/town-branch/town-branch-small-batch-straight-rye-whiskey", "reviewer": "Town Branch", "text": "Whiskey & Spirits » Town Branch » Town Branch ® Small Batch Straight Rye Whiskey Town Branch ® Small Batch Straight Rye Whiskey 2026-01-21T13:16:26-05:00 Town Branch® Small Batch KENTUCKY Straight Rye Whiskey Town Branch® Kentucky Straight Rye Whiskey is a non-age-stated, small-batch blend, bottled at 100 proof, non-chill filtered, and averaging about seven years in age. It is released each year under allocation, celebrated every August during National Rye Month. This rye opens with a spicy, inviting aroma and unfolds on the palate with notes of smooth vanilla, dried fruit—including hints of tropical flavors—rich oak, and subtle peppery spice, finishing warm and dry."}, {"product_id": "ab0e207d-96fd-4f33-aab9-8d2fe55f6525", "source": "whistlepigwhiskey.com", "source_url": "https://www.whistlepigwhiskey.com/product/whistlepig-18-years", "reviewer": "WhistlePig", "text": "WhistlePig Double Malt Rye is our oldest Rye, patiently mellowed for 18 years. Before industrial distillation, America's original farmers would malt a small portion of their grain to start fermentation, the essential step that turns water and rye into glorious whiskey. As a nod to the farmers, Double Malt Rye is crafted from a mash bill of Rye, Malted Rye and Malted Barley. History aside, these grains unite in a show-stopping Rye Whiskey that stretches far and wide across the flavor spectrum. Its base of 79% Rye delivers bold, peppery spice, while 15% Malted Rye adds soft, floral and earthy character. A final 6% of malted barley brings rich, sweet, toasted notes. At once bold, complex, delicate and elegant, WhistlePig 18 is the whiskey that your most memorable toasts require, and a gem on any bar. Each annual edition of our Double Malt Rye is crowned with a bespoke glass topper, handmade in Vermont. Certified Kosher."}, {"product_id": "4dcf86e2-e1a2-441d-a61c-63ddd20c334e", "source": "whistlepigwhiskey.com", "source_url": "https://www.whistlepigwhiskey.com/product/snout-to-tail-bourbon-aged-10-years", "reviewer": "WhistlePig", "text": "We're Flipping Bourbon on Its Head WhistlePig's Snout-to-Tail Bourbon challenges tradition with bold innovation. Aged 10 years and crafted with a double-barrel-head aging process, it's infused with rich caramel, vanilla, and smoky maple notes thanks to Vermont oak and smoked maple wood. Each barrel is flipped 180 degrees during aging for unmatched complexity. Bottled at 88 proof, it's smooth, bold, and perfect for sipping neat or on the rocks. Pair it with our 10-Year Rye for the ultimate duo. Ready to taste Bourbon reimagined? Grab a bottle and experience WhistlePig's fearless craft."}, {"product_id": "b58adcb6-d7e4-4e91-ac23-fed21fe73032", "source": "russellsreserve.com", "source_url": "https://www.russellsreserve.com/our-products/6-year-old-rye/", "reviewer": "Wild Turkey", "text": "Russell's Reserve 6 Year Old Rye Whiskey is complex and spicy, offering a lively flavor profile of citrus zest and subtle caramel with a black pepper finish."}, {"product_id": "6c459181-a90a-4dd1-81bd-b12fa8ebda14", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/wild-turkey-bourbon/", "reviewer": "Wild Turkey", "text": "With notes of vanilla, caramel, and hints of honey and orange, our Wild Turkey Bourbon Whiskey finishes with a full, rich flavor. Try it neat or in a cocktail."}, {"product_id": "63cafff9-8120-4eae-a8b3-7383d602ce5f", "source": "yellowstonebourbon.com", "source_url": "https://yellowstonebourbon.com/rum-cask/", "reviewer": "Yellowstone", "text": "| Nose:| Gingerbread, poached pear and fresh-cut hay.| Palate:| Toasted marshmallow, crème brûlée, toffee and toasted oak. | Finish:| Tobacco, clove and cocoa-seasoned oak with a long honey finish. | DOUBLE PLATINUM| Rum Cask 2025 ASCOT Awards| GOLD MEDAL| 2025 San Francisco World Spirits Competition| 91 POINTS| Rum Cask 2025 San Francisco World Spirits Competition| PLATINUM| 2024 ASCOT Awards| FEATURED COCKTAIL | RUM CASK RUNNER| A Rum Runner that calls Kentucky home. | MAKE IT| YELLOWSTONE SPECIAL FINISHES COLLECTION – RUM CASK |"}, {"product_id": "2a78f5a1-6906-4340-a12b-de1a00a1a3e4", "source": "yellowstonebourbon.com", "source_url": "https://yellowstonebourbon.com/select-bourbon/", "reviewer": "Yellowstone", "text": "| Nose:| Rye spice with soft, leathered cherries.| Palate:| Smoked caramel with hints of vanilla and honey.| Finish:| Smoky oak brown sugar.| GOLD| Select 2025 ASCOT Awards| DOUBLE GOLD| 2024 SIP Awards| GOLD| 2023 ASCOT Awards| GOLD| 2023 SIP Awards| DOUBLE GOLD| 2023 Bartender Spirits| GOLD| 2022 San Francisco World Spirits Competition| FEATURED COCKTAIL | TIMBER SMASH| Yellowstone Bourbon, spiced rum, pineapple and mint combine to make a whiskey smash with a tiki flourish. | MAKE IT| Bourbon options available from Yellowstone. Learn about our premier Yellowstone select bourbon |"}, {"product_id": "d318655d-a1ab-4db7-881a-e7a1b3ab682b", "source": "yellowstonebourbon.com", "source_url": "https://yellowstonebourbon.com/small-batch-107/", "reviewer": "Yellowstone", "text": "| Nose:| Caramel and vanilla with hints of chocolate and oak| Taste:| Caramel, oak, honey and cherry| PLATINUM| Small Batch 2025 ASCOT Awards| GOLD| Small Batch 2025 San Francisco World Spirits Competition| 94 POINTS| Small Batch 2025 San Francisco World Spirits Competition| FEATURED COCKTAIL | TIMBER SMASH| Yellowstone Bourbon, spiced rum, pineapple and mint combine to make a whiskey smash with a tiki flourish. | MAKE IT| --> | Bourbon options available from Yellowstone. Learn about our premier Yellowstone select bourbon |"}, {"product_id": "40a72917-877b-4e74-b657-30532defe742", "source": "yellowstonebourbon.com", "source_url": "https://yellowstonebourbon.com/special-finishes-collection-toasted/", "reviewer": "Yellowstone", "text": "| Nose:| Toasted caramel, vanilla, hints of fall spices and cinnamon.| Palate:| Walnut, toffee, black tea and white pepper.| Finish:| Cocoa and tobacco with a crisp oak finish.| PLATINUM| Toasted 2025 ASCOT Awards| GOLD MEDAL| 2025 San Francisco World Spirits Competition| 93 POINTS| Toasted 2025 San Francisco World Spirits Competition| DOUBLE GOLD| 2024 San Francisco World Spirits Competition| GOLD| 2024 ASCOT Awards| DOUBLE GOLD| 2024 SIP Awards| BUY BY THE BARREL| Are you a retailer interested in joining our barrel program? Learn more about scheduling your Limestone Branch Distillery visit t"}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
